def find_continuous_groups(row):
    """Find groups of consecutive 1s"""
    groups = []
    start = None
    for c, val in enumerate(row):
        if val == 1:
            if start is None:
                start = c
        else:
            if start is not None:
                groups.append((start, c-1))  # start (inclusive) to end (exclusive)
                start = None
    if start is not None:
        groups.append((start, len(row)-1))
    return groups

def apply_pattern_based_on_groups(grid):
    """Pattern based on continuous groups of 1s"""
    result = [row[:] for row in grid]
    for r in range(len(grid)):
        row = grid[r]
        for start, end in find_continuous_groups(row):
            # For each group, apply pattern to first and last element
            for c in [start, end]:
                if c < len(row):
                    # Write pattern centered at c
                    if c > 0:
                        result[r][c-1] = 5  # left gets 5
                    result[r][c] = 6  # center gets 6
                    if c < len(row) - 1:
                        result[r][c+1] = 6  # right gets 6
    return result

